sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.headword, e.headword_norm, e.root, e.root_source, e.definitions_text, e.translation_en, e.domain, d.name_ar, d.name_en, d.source_type, d.period FROM entries e JOIN dictionaries d ON e.dictionary_id=d.id WHERE e.headword_norm IN ('اشارة','الاشارة','تبيان','التبيان','تجلية','التجلية','ابراز','الابراز','تمثيل','التمثيل','استشهاد','الاستشهاد') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST LIMIT 80;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
for r in data:
    print(f\"entry_id={r['entry_id']} headword={r['headword']} norm={r['headword_norm']} root={r['root']} src={r['root_source']} dict={r['dict_name_ar'] or r['dict_name_en']} src_type={r['source_type']}\")
    if r['definitions_text']:
        print(f\"  def: {r['definitions_text'][:200]}\")
    if r['translation_en']:
        print(f\"  en: {r['translation_en']}\")
    if r['domain']:
        print(f\"  domain: {r['domain']}\")
